    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = BabyApeCoin(TARGET);
        owner = token.owner();
        victim = makeAddr("victim");

        // Directly satisfy victim balance precondition.
